from abc import ABCMeta, abstractmethod
from taf.selenium.sbts.pages.menu import Menu


class NavigatablePage(object):
    __metaclass__ = ABCMeta

    _menu = None

    def __init__(self, driver):
        if not self._menu:
            self._menu = Menu(driver)

    def navigate_to(self, interval=3, retry=5):
        """
        navigate to page by menu route list

        :return: object, corresponding page instance
        """
        if self._get_route_list() and len(self._get_route_list()):
            self._menu.open_page(self._get_route_list(), interval=interval, retry=retry)

    @abstractmethod
    def _get_route_list(self):
        pass
